from typing import Any, Dict, List, Optional


def handle_type_a(item: Dict[str, Any]) -> Dict[str, Any]:
    value = item["value"] * 2
    category = "high" if value > 100 else "low"
    return {"id": item["id"], "value": value, "category": category}


def handle_type_b(item: Dict[str, Any]) -> Dict[str, Any]:
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}


def handle_type_c(item: Dict[str, Any]) -> Dict[str, Any]:
    if item["value"] < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": item["value"], "category": "passthrough"}


HANDLERS: Dict[str, Any] = {
    "A": handle_type_a,
    "B": handle_type_b,
    "C": handle_type_c,
}


def dispatch(item: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    handler = HANDLERS.get(item.get("type"))
    if handler is None:
        return None
    return handler(item)


def process_data(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    results: List[Dict[str, Any]] = []
    for item in data:
        result = dispatch(item)
        if result is not None:
            results.append(result)
    return results

