}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function validateUser(value: unknown): value is User {
  if (!isRecord(value)) {
    return false;
  }

  if (typeof value.id !== "number" || !Number.isInteger(value.id)) {
    return false;
  }

  if (typeof value.name !== "string" || value.name.length === 0) {
    return false;
  }

  if (typeof value.email !== "string" || !value.email.includes("@")) {
    return false;
  }

  const preferences = value.preferences;

  if (!isRecord(preferences)) {
    return false;
  }

  if (typeof preferences.theme !== "string") {
    return false;
  }

  if (typeof preferences.notifications !== "boolean") {
    return false;
  }

  if (typeof preferences.language !== "string") {
    return false;
  }

  const tags = value.tags;

  if (!Array.isArray(tags) || !tags.every((tag) => typeof tag === "string")) {
    return false;
  }

  if (typeof value.last_login !== "string" || Number.isNaN(Date.parse(value.last_login))) {
    return false;
