#!/usr/bin/env python3
"""
CLI tool to summarize log levels in .log files.

Usage:
    python log_summary.py /path/to/logs --min-errors 3
"""

import argparse
import re
import sys
from pathlib import Path

LOG_LEVELS = ("INFO", "WARN", "ERROR", "DEBUG")


def compile_patterns():
    """Compile regex patterns for each log level."""
    return {level: re.compile(rf"\b{level}\b") for level in LOG_LEVELS}


def count_log_levels(path, patterns):
    """
    Count occurrences of each log level in a single file.

    Returns:
        dict with counts, or None if the file could not be read.
    """
    counts = {level: 0 for level in LOG_LEVELS}

    try:
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line in handle:
                for level in LOG_LEVELS:
                    counts[level] += len(patterns[level].findall(line))
    except OSError as exc:
        print(f"Skipping {path}: {exc}", file=sys.stderr)
        return None

    return counts


def render_table(rows):
    """Render the summary table as a string."""
    headers = ("file", "INFO", "WARN", "ERROR", "DEBUG")
    table = [headers] + rows

    widths = [
        max(len(str(row[i])) for row in table)
        for i in range(len(headers))
    ]

    output = []
    for index, row in enumerate(table):
        output.append(
            " | ".join(
                str(cell).ljust(widths[i])
                for i, cell in enumerate(row)
            )
        )
        if index == 0:
            output.append("-+-".join("-" * width for width in widths))

    return "\n".join(output)


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Count log levels in .log files in a directory."
    )
    parser.add_argument(
        "directory",
        type=Path,
        help="Directory containing .log files",
    )
    parser.add_argument(
        "--min-errors",
        type=int,
        default=0,
        metavar="N",
        help="Only show files with at least N ERROR entries",
    )

    args = parser.parse_args(argv)

    if args.min_errors < 0:
        parser.error("--min-errors must be >= 0")

    directory = args.directory.expanduser()

    if not directory.exists():
        parser.error(f"Directory not found: {directory}")

    if not directory.is_dir():
        parser.error(f"Not a directory: {directory}")

    log_files = sorted(
        (
            path
            for path in directory.iterdir()
            if path.is_file() and path.suffix.lower() == ".log"
        ),
        key=lambda p: p.name,
    )

    if not log_files:
        print("No .log files found.")
        return 0

    patterns = compile_patterns()
    rows = []

    for path in log_files:
        counts = count_log_levels(path, patterns)
        if counts is None:
            continue

        if counts["ERROR"] >= args.min_errors:
            rows.append(
                [
                    path.name,
                    counts["INFO"],
                    counts["WARN"],
                    counts["ERROR"],
                    counts["DEBUG"],
                ]
            )

    if not rows:
        print("No files matched the filter.")
        return 0

    print(render_table(rows))
    return 0


if __name__ == "__main__":
    sys.exit(main())
